INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q645905', 'Battle of Cedynia', 'The Battle of Cedynia (also known as the Battle of Zehden) was fought on 24 June 972 near the Oder river, when an army led by Mieszko I of Poland defeated the forces of the Saxon margrave Hodo (or Odo I of Lusatia). Whether the battle actually took place near the modern-day town of Cedynia is disputed in modern scholarship.', 972, 6, 24, NULL, NULL, NULL, 'day', '24 June 972', 55, 'https://en.wikipedia.org/wiki/Battle_of_Cedynia'),
  ('Q2667645', 'Mongol invasion of Poland', 'The Mongol invasion of Poland from late 1240 to 1241 culminated in the Battle of Legnica, where the Mongols defeated an alliance which included forces from fragmented Poland and their allies, led by Henry II the Pious, the Duke of Silesia and High Duke of Poland. The first invasion''s intention was to secure the flank of the main Mongolian army attacking the Kingdom of Hungary.', 1240, NULL, NULL, 1241, NULL, NULL, 'year', '1240–1241', 55, 'https://en.wikipedia.org/wiki/First_Mongol_invasion_of_Poland'),
  ('Q159512', 'Battle of Legnica', 'The Battle of Legnica (Polish: bitwa pod Legnicą), also known as the Battle of Liegnitz (German: Schlacht von Liegnitz) or Battle of Wahlstatt (German: Schlacht bei Wahlstatt), was fought between the Mongol Empire and combined European forces at the village of Legnickie Pole (Wahlstatt), approximately 10 kilometres (6 mi) southeast of the city of Legnica in the Duchy of Silesia on 9 April 1241. A combined force of Poles and Moravians under the command of Duke Henry II the Pious of Silesia, supported by feudal nobility and a few knights from military orders sent by Pope Gregory IX, attempted…', 1241, 4, 9, NULL, NULL, NULL, 'day', '9 April 1241', 71, 'https://en.wikipedia.org/wiki/Battle_of_Legnica'),
  ('Q33570', 'Battle of Grunwald', 'The Battle of Grunwald, also known as the (First) Battle of Tannenberg or the Battle of Žalgiris, was fought on 15 July 1410 during the Polish–Lithuanian–Teutonic War. The alliance of the Crown of the Kingdom of Poland and the Grand Duchy of Lithuania, led respectively by King Władysław II Jagiełło (Jogaila), and Grand Duke Vytautas, decisively defeated the Teutonic Order, led by Grand Master Ulrich von Jungingen.', 1410, 7, 15, NULL, NULL, NULL, 'day', '15 July 1410', 81, 'https://en.wikipedia.org/wiki/Battle_of_Grunwald'),
  ('Q3485791', 'Polish Golden Age', 'The Polish Golden Age (Polish: Złoty Wiek Polski [ˈzwɔ.tɘ ˈvjɛk ˈpɔl.ski] ) was the Renaissance period in the Kingdom of Poland and subsequently in the Polish–Lithuanian Commonwealth, which started in the late 15th century. Historians argue that the Polish Golden Age ended by the mid-17th century, when Poland was ravaged by the Khmelnytsky Uprising (1648–57) and by the Swedish and Russian invasion.', 1507, NULL, NULL, 1572, NULL, NULL, 'year', '1507–1572', 55, 'https://en.wikipedia.org/wiki/Polish_Golden_Age'),
  ('Q703763', 'Treaty of Stettin', 'The Treaty of Stettin (German: Frieden von Stettin, Swedish: Freden i Stettin, Danish: Freden i Stettin) of 13 December 1570, ended the Northern Seven Years'' War fought between Sweden and Denmark with its internally fragmented alliance of Lübeck and Poland. It also settled Swedish, Danish, and Holy Roman Imperial claims regarding the Livonian War.', 1570, 12, 13, NULL, NULL, NULL, 'day', '13 December 1570', 56, 'https://en.wikipedia.org/wiki/Treaty_of_Stettin_(1570)'),
  ('Q1044829', 'Polish–Muscovite War', 'The Polish–Russian War was a conflict fought between the Polish–Lithuanian Commonwealth and the Tsardom of Russia from 1609 to 1618. Russia had been experiencing the Time of Troubles since the death of Tsar Feodor I in 1598, which caused political instability and a violent succession crisis upon the extinction of the Rurik dynasty; furthermore, a major famine ravaged the country from 1601 to 1603.', 1605, NULL, NULL, 1618, NULL, NULL, 'year', '1605–1618', 69, 'https://en.wikipedia.org/wiki/Polish%E2%80%93Russian_War_(1609%E2%80%931618)'),
  ('Q426926', 'Battle of Warsaw', 'The Battle of Warsaw (German: Schlacht von Warschau; Polish: Bitwa pod Warszawą; Swedish: Tredagarsslaget vid Warschau) took place near Warsaw on July 28–July 30 [O.S. July 18–20] 1656, between the armies of the Polish–Lithuanian Commonwealth and Sweden and Brandenburg. It was a major battle in the Second Northern War between Poland and Sweden in the period 1655–1660, also known as The Deluge.', 1656, NULL, NULL, 1656, 7, 30, 'year', '1656', 58, 'https://en.wikipedia.org/wiki/Battle_of_Warsaw_(1656)'),
  ('Q704762', 'Battle of Klissow', 'The Battle of Kliszów (also spelled Klissow or Klezow) took place on 19 July 1702, near the village of Kliszów in the Polish–Lithuanian Commonwealth during the Great Northern War. A Swedish army under the command of King Charles XII of Sweden defeated a Polish–Saxon army twice the size that was led by King Augustus II the Strong.', 1702, 7, 19, NULL, NULL, NULL, 'day', '19 July 1702', 53, 'https://en.wikipedia.org/wiki/Battle_of_Klisz%C3%B3w'),
  ('Q212658', 'War of the Polish Succession', 'The War of the Polish Succession (Polish: Wojna o sukcesję polską; 1733–35) was a major European conflict sparked by a civil war in the Polish–Lithuanian Commonwealth over the succession to Augustus II the Strong, which the other European powers widened in pursuit of their own national interests. France and Spain, the two Bourbon powers, tested the power of the Austrian Habsburgs in Western Europe, as did the Kingdom of Prussia, whilst Saxony and Russia mobilized to support the eventual victor.', 1733, 10, 10, 1735, 10, 3, 'day', '10 October 1733 – 3 October 1735', 74, 'https://en.wikipedia.org/wiki/War_of_the_Polish_Succession'),
  ('Q2354105', 'Siege of Danzig', 'The siege of Danzig of 1734 was the Russian encirclement (22 February – 30 June) and capture of the Polish city-port of Gdańsk, during the War of Polish Succession. It was the first time that troops of France and Russia had met as foes in the field.', 1734, NULL, NULL, 1734, 7, 9, 'year', '1734', 53, 'https://en.wikipedia.org/wiki/Siege_of_Danzig_(1734)'),
  ('Q663435', 'Battle of Mollwitz', 'The Battle of Mollwitz was fought by Prussia and Austria on 10 April 1741, during the First Silesian War (in the early stages of the War of the Austrian Succession). It was the first battle of the new Prussian King Frederick II, in which both sides made numerous military blunders.', 1741, 4, 10, NULL, NULL, NULL, 'day', '10 April 1741', 61, 'https://en.wikipedia.org/wiki/Battle_of_Mollwitz'),
  ('Q688448', 'Battle of Hohenfriedberg', 'The Battle of Hohenfriedberg or Hohenfriedeberg (now Dobromierz, Poland), also known as the Battle of Striegau (now Strzegom, Poland) was one of Frederick the Great''s most admired victories. Frederick''s Prussian army decisively defeated an Austro-Saxon army under Prince Charles Alexander of Lorraine on June 4, 1745, during the Second Silesian War – part of the War of the Austrian Succession.', 1745, 6, 4, NULL, NULL, NULL, 'day', '4 June 1745', 60, 'https://en.wikipedia.org/wiki/Battle_of_Hohenfriedberg'),
  ('Q313435', 'Battle of Leuthen', 'The Battle of Leuthen was fought on 5 December 1757 between Frederick the Great''s Prussian Army and an Austrian army commanded by Prince Charles of Lorraine and Count Leopold Joseph von Daun. Frederick used maneuver warfare and knowledge of the terrain to rout the larger Austrian force completely.', 1757, 12, 5, NULL, NULL, NULL, 'day', '5 December 1757', 63, 'https://en.wikipedia.org/wiki/Battle_of_Leuthen'),
  ('Q695312', 'Battle of Breslau', 'The Battle of Breslau (also known as the Battle on the Lohe) was fought on 22 November 1757 in Breslau (now Wrocław, Poland) during the Third Silesian War (part of the Seven Years'' War). A Prussian army of 28,000 men fought an Austrian army of 60,000 men.', 1757, 11, 22, NULL, NULL, NULL, 'day', '22 November 1757', 55, 'https://en.wikipedia.org/wiki/Battle_of_Breslau_(1757)'),
  ('Q663405', 'Battle of Zorndorf', 'The Battle of Zorndorf, during the Seven Years'' War, was fought on 25 August 1758 between Russian troops commanded by Count William Fermor and a Prussian army commanded by King Frederick the Great. The battle was tactically inconclusive, with both armies holding their ground and claiming victory.', 1758, 8, 25, NULL, NULL, NULL, 'day', '25 August 1758', 63, 'https://en.wikipedia.org/wiki/Battle_of_Zorndorf'),
  ('Q170400', 'Battle of Kunersdorf', 'The Battle of Kunersdorf occurred on 12 August 1759 near Kunersdorf (now Kunowice, Poland) immediately east of Frankfurt an der Oder. Part of the Third Silesian War and the wider Seven Years'' War, the battle involved over 100,000 men.', 1759, 8, 12, NULL, NULL, NULL, 'day', '12 August 1759', 64, 'https://en.wikipedia.org/wiki/Battle_of_Kunersdorf'),
  ('Q697913', 'Battle of Landeshut', 'The Battle of Landeshut was an engagement fought on 23 June 1760 during the Third Silesian War (part of the Seven Years'' War). A Prussian army of 12,000 men under General Heinrich August de la Motte Fouqué fought an Austrian army of over 28,000 men under Ernst Gideon von Laudon and suffered a defeat, with its commander wounded and taken prisoner.', 1760, 6, 23, NULL, NULL, NULL, 'day', '23 June 1760', 56, 'https://en.wikipedia.org/wiki/Battle_of_Landeshut_(1760)'),
  ('Q701139', 'Battle of Liegnitz', 'The Battle of Liegnitz on 15 August 1760 saw Frederick the Great''s Prussian Army defeat the Austrian army under Ernst von Laudon during the Third Silesian War (part of the Seven Years'' War). The armies collided around the town of Liegnitz (now Legnica, Poland) in Lower Silesia.', 1760, 8, 15, NULL, NULL, NULL, 'day', '15 August 1760', 55, 'https://en.wikipedia.org/wiki/Battle_of_Liegnitz_(1760)'),
  ('Q1347209', 'Battle of Praga', 'The Battle of Praga or the Second Battle of Warsaw of 1794, also known in Russian and German as the Storming of Praga (Russian: Штурм Праги) and in Polish as the Defence of Praga (Polish: Obrona Pragi), was a successful Russian assault on Praga, the easternmost community of Warsaw, during the Kościuszko Uprising in 1794. It was followed by a massacre (known as the Massacre of Praga) of the civilian population of Praga.', 1794, 11, 4, NULL, NULL, NULL, 'day', '4 November 1794', 53, 'https://en.wikipedia.org/wiki/Battle_of_Praga'),
  ('Q1577800', 'Battle of Racławice', 'The Battle of Racławice (Polish: Bitwa pod Racławicami) was one of the first battles of the Kościuszko Uprising against Russia. It was fought on 4 April 1794 near the village of Racławice in Lesser Poland.', 1794, 4, 4, NULL, NULL, NULL, 'day', '4 April 1794', 57, 'https://en.wikipedia.org/wiki/Battle_of_Rac%C5%82awice'),
  ('Q605977', 'War of the Fourth Coalition', 'The War of the Fourth Coalition (French: Guerre de la Quatrième Coalition) was a war spanning 1806–1807 that saw a multinational coalition fight against Napoleon''s French Empire, subsequently being defeated. The main coalition partners were Prussia and Russia with Saxony, Sweden, and Great Britain also contributing.', 1806, 10, NULL, 1807, NULL, NULL, 'month', 'October 1806 – 1807', 73, 'https://en.wikipedia.org/wiki/War_of_the_Fourth_Coalition'),
  ('Q901954', 'Siege of Danzig', 'The siege of Danzig (19 March – 24 May 1807) was the French encirclement and capture of Danzig during the War of the Fourth Coalition. On 19 March 1807, around 27,000 French troops under Marshal Lefebvre besieged around 14,400 Prussian troops under Marshal Kalckreuth garrisoning the city of Danzig.', 1807, 3, 19, 1807, 5, 2, 'day', '19 March 1807 – 2 May 1807', 56, 'https://en.wikipedia.org/wiki/Siege_of_Danzig_(1807)'),
  ('Q926489', 'Battle of Heilsberg', 'The Battle of Heilsberg took place on 10 June [O.S. 29 May] 1807 off the town of Heilsberg (now Lidzbark Warmiński), during the Napoleonic Wars. In it, Joachim Murat''s French troops began the offensive on Leonty (Levin) Bennigsen''s Russian force ahead of schedule.', 1807, 6, 10, NULL, NULL, NULL, 'day', '10 June 1807', 53, 'https://en.wikipedia.org/wiki/Battle_of_Heilsberg'),
  ('Q516282', 'Battle of Raszyn', 'The Battle of Raszyn was fought on 19 April 1809 between armies of the Austrian Empire under Archduke Ferdinand Karl Joseph of Austria-Este and the Duchy of Warsaw under Józef Antoni Poniatowski, as part of the War of the Fifth Coalition in the Napoleonic Wars. The battle was not decisive, but it did result in the Austrians obtaining their goal by capturing the Polish capital Warsaw.', 1809, 4, 19, NULL, NULL, NULL, 'day', '19 April 1809', 55, 'https://en.wikipedia.org/wiki/Battle_of_Raszyn_(1809)'),
  ('Q685372', 'Kraków Uprising', 'The Kraków Uprising (Polish: powstanie krakowskie, rewolucja krakowska; German: Krakauer Aufstand; Russian: краковское восстание, romanized: krakovskoye vosstaniye) of 1846 was an attempt, led by Polish insurgents such as Jan Tyssowski and Edward Dembowski, to incite a fight for national independence. The uprising was centered on the city of Kraków, the capital of the small Free City of Cracow.', 1846, 2, 21, 1846, 3, 3, 'day', '21 February 1846 – 3 March 1846', 59, 'https://en.wikipedia.org/wiki/Krak%C3%B3w_Uprising'),
  ('Q28205', 'Battle of the Vistula River', 'The Battle of the Vistula River, also known as the Battle of Warsaw and Ivangorod, was a major Russian victory against Germany and Austria-Hungary on the Eastern Front during the First World War. The battle is one of the largest and most important battles in the First World War, one of the most striking victories of the Russian army, which showed that the Russian troops were strong and could resist the Germans.', 1914, 9, 29, 1914, 10, 31, 'day', '29 September 1914 – 31 October 1914', 57, 'https://en.wikipedia.org/wiki/Battle_of_the_Vistula_River'),
  ('Q153858', 'Battle of Tannenberg', 'The Battle of Tannenberg, also known as the Second Battle of Tannenberg, was fought between Russia and Germany between 26 and 30 August 1914, the first month of World War I. The battle resulted in the encirclement and the almost complete destruction of the Russian 2nd Army by the German 8th Army and the suicide of its commanding general, Alexander Samsonov. A series of follow-up battles (First Masurian Lakes) led to the ousting of the Russian 1st Army from East Prussia.', 1914, 8, 23, 1914, 8, 30, 'day', '23 August 1914 – 30 August 1914', 75, 'https://en.wikipedia.org/wiki/Battle_of_Tannenberg'),
  ('Q689972', 'Battle of Kraśnik', 'The Battle of Kraśnik (German: Schlacht von Kraśnik) started on August 23, 1914, in the province of Galicia and the adjacent areas across the border in the Russian Empire, in northern Austria (in present-day Poland), and ended two days later. The Austro-Hungarian 1st Army defeated the Russian 4th Army.', 1914, NULL, NULL, 1914, 8, 25, 'year', '1914', 57, 'https://en.wikipedia.org/wiki/Battle_of_Kra%C5%9Bnik'),
  ('Q696300', 'Battle of Łódź', 'The Battle of Łódź (German: Schlacht um Łódź) or Lodz operation (Russian: Лодзинская операция, romanized: Lodzinskaya operatsia) took place from 11 November to 6 December 1914, near the city of Łódź in Poland. Battles were fought between German units of the 8th Army, 9th Army, Austrian 1st Army, and the Russian 1st, 2nd, and 5th Armies, in harsh winter conditions.', 1914, NULL, NULL, 1914, 12, 6, 'year', '1914', 58, 'https://en.wikipedia.org/wiki/Battle_of_%C5%81%C3%B3d%C5%BA_(1914)'),
  ('Q698828', 'Siege of Przemyśl', 'The Siege of Przemyśl was the longest siege in Europe during the First World War, and the second-longest in the entire conflict, after the Siege of Medina. The siege was a crushing defeat of the Austro-Hungarian Army by the Russian Army.', 1914, 9, 16, 1915, 3, 22, 'day', '16 September 1914 – 22 March 1915', 65, 'https://en.wikipedia.org/wiki/Siege_of_Przemy%C5%9Bl'),
  ('Q670489', 'Gorlice–Tarnów Offensive', 'The Gorlice–Tarnów offensive during World War I was initially conceived as a minor German offensive to relieve Russian pressure on the Austro-Hungarians to their south on the Eastern Front, but resulted in the Central Powers'' chief offensive effort of 1915, causing the total collapse of the Russian lines and their retreat far into Russia. The continued series of actions lasted the majority of the campaigning season for 1915, starting in early May and only ending due to bad weather in October.', 1915, 6, 22, 1915, 6, NULL, 'day', '22 June 1915 – June 1915', 65, 'https://en.wikipedia.org/wiki/Gorlice%E2%80%93Tarn%C3%B3w_offensive'),
  ('Q2467678', 'Battle of Bolimów', 'The Battle of Humin-Bolimów was an inconclusive battle of World War I fought between January 14 and February 28, 1915 between the Imperial German Army and Russia. The battle is considered a preliminary to the Second Battle of the Masurian Lakes.', 1915, 1, 31, NULL, NULL, NULL, 'day', '31 January 1915', 57, 'https://en.wikipedia.org/wiki/Battle_of_Humin-Bolim%C3%B3w'),
  ('Q703893', 'Silesian Uprisings', 'The Silesian Uprisings were a series of three uprisings from August 1919 to July 1921 in Upper Silesia, which was part of the Weimar Republic at the time. Ethnic Polish and Polish-Silesian insurrectionists, seeking to have the area transferred to the newly founded Polish Republic, fought German police and paramilitary forces, which sought to keep the area part of the new German state founded after World War I and the subsequent revolutions in Germany.', 1919, 8, 26, 1921, 7, 21, 'day', '26 August 1919 – 21 July 1921', 62, 'https://en.wikipedia.org/wiki/Silesian_Uprisings'),
  ('Q821283', 'Battle of Warsaw', 'The Battle of Warsaw (Polish: Bitwa Warszawska; Russian: Варшавская битва, Varshavskaya bitva), also known as the Miracle on the Vistula (Polish: Cud nad Wisłą), was a series of battles that resulted in a decisive Polish victory and complete disintegration of the Red Army in August 1920 during the Polish–Soviet War. After the Polish Kiev offensive, Soviet forces launched a successful counterattack in summer 1920, forcing the Polish army to retreat westward.', 1920, NULL, NULL, 1920, 8, 25, 'year', '1920', 73, 'https://en.wikipedia.org/wiki/Battle_of_Warsaw_(1920)'),
  ('Q1495944', 'Polish–Lithuanian War', 'The Polish–Lithuanian War was an undeclared war fought in the aftermath of World War I between newly independent Lithuania and Poland, with fighting mainly in the Vilnius and Suwałki regions, which was part of the Lithuanian Wars of Independence and lasted from May 1919 to 29 November 1920. From the spring of 1920 onward, the conflict happened alongside the wider Polish–Soviet War and was affected by its progress.', 1920, 11, 29, 1920, NULL, NULL, 'day', '1920', 64, 'https://en.wikipedia.org/wiki/Polish%E2%80%93Lithuanian_War'),
  ('Q1349575', 'Warsaw Convention', 'The Convention for the Unification of certain rules relating to international carriage by air, commonly known as the Warsaw Convention, is an international convention which regulates liability for international carriage of persons, luggage, or goods performed by aircraft for reward. Originally signed in 1929 in Warsaw (hence the name), it was amended in 1955 at The Hague, Netherlands, and in 1971 in Guatemala City, Guatemala.', 1929, NULL, NULL, NULL, NULL, NULL, 'year', '1929', 63, 'https://en.wikipedia.org/wiki/Warsaw_Convention'),
  ('Q150812', '1939 Invasion of Poland', 'The invasion of Poland, also known as the September Campaign, Polish Campaign, and Polish Defensive War of 1939 (1 September – 6 October 1939), was a joint attack on the Republic of Poland by Nazi Germany, the Slovak Republic, and the Soviet Union, which marked the beginning of World War II. The invasion began on 1 September 1939 when Germany marched into Poland, preceded by the Danzig crisis and by the Molotov–Ribbentrop Pact between Germany and the Soviet Union, which was signed one week before and approved by the Supreme Soviet of the Soviet Union one day before the invasion. On 17…', 1939, 9, 1, 1939, 10, 6, 'day', '1 September 1939 – 6 October 1939', 83, 'https://en.wikipedia.org/wiki/Invasion_of_Poland'),
  ('Q165549', 'Battle of the Bzura', 'The Battle of the Bzura (or the Battle of Kutno) was the largest battle of the German invasion of Poland and was fought from 9 to 19 September 1939. It was a Polish counter-attack against the Germans.', 1939, 9, 9, 1939, 9, 19, 'day', '9 September 1939 – 19 September 1939', 67, 'https://en.wikipedia.org/wiki/Battle_of_the_Bzura'),
  ('Q175113', 'Bloody Sunday', 'Bloody Sunday (German: Bromberger Blutsonntag; Polish: Krwawa niedziela) was a sequence of violent events that took place in Bydgoszcz (German: Bromberg), a Polish city with a sizable German minority, between 3 and 4 September 1939, during the German invasion of Poland. Standing in the path of the German army''s advance during the early days of the invasion, tensions quickly escalated in Bydgoszcz between the city''s sizable German-speaking minority and its Polish majority.', 1939, 9, 3, NULL, NULL, NULL, 'day', '3 September 1939', 61, 'https://en.wikipedia.org/wiki/Bloody_Sunday_(1939)'),
  ('Q182240', 'Siege of Warsaw', 'The Siege of Warsaw was fought between the Polish Warsaw Army (Polish: Armia Warszawska, Armia Warszawa) garrisoned and entrenched in Warsaw and the invading German Army. It began with huge aerial bombardments initiated by the Luftwaffe starting on September 1, 1939 following the German invasion of Poland.', 1939, 9, 8, 1939, 9, 28, 'day', '8 September 1939 – 28 September 1939', 67, 'https://en.wikipedia.org/wiki/Siege_of_Warsaw_(1939)'),
  ('Q533034', 'Battle of Westerplatte', 'The Battle of Westerplatte was the first battle of the German invasion of Poland, marking the start of World War II in Europe. It occurred on the Westerplatte peninsula in the harbour of the Free City of Danzig (now Gdańsk, Poland).', 1939, 9, 1, 1939, 9, 7, 'day', '1 September 1939 – 7 September 1939', 69, 'https://en.wikipedia.org/wiki/Battle_of_Westerplatte'),
  ('Q564388', 'Defense of the Polish Post Office in Danzig', 'The Defence of the Polish Post Office in Gdańsk (Danzig) was one of the first acts of World War II in Europe, as part of the September Campaign. On 1 September 1939 the Invasion of Poland was initiated by Germany when the battleship Schleswig-Holstein opened fire on the Polish-controlled harbor of Danzig, around 04:45.', 1939, 9, 1, NULL, NULL, NULL, 'day', '1 September 1939', 58, 'https://en.wikipedia.org/wiki/Defence_of_the_Polish_Post_Office_in_Danzig'),
  ('Q641183', 'Battle of Kock', 'The Battle of Kock was the final battle in the invasion of Poland at the beginning of World War II in Europe. It took place from 2 to 5 October 1939, near the town of Kock in Poland.', 1939, 10, 2, 1939, 10, 5, 'day', '2 October 1939 – 5 October 1939', 53, 'https://en.wikipedia.org/wiki/Battle_of_Kock_(1939)'),
  ('Q694500', 'Battle of Wizna', 'The Battle of Wizna (Polish: Obrona Wizny) was fought between September 7 and September 10, 1939, between the forces of Poland and Germany during the initial stages of the invasion of Poland, which marked the beginning of the Second World War in Europe. According to Polish historian Leszek Moczulski, between 350 and 720 Poles defended a fortified line for three days against more than 40,000 Germans.', 1939, NULL, NULL, 1939, 9, 10, 'year', '1939', 58, 'https://en.wikipedia.org/wiki/Battle_of_Wizna'),
  ('Q704550', 'Battle of Hel', 'The Battle of Hel (Polish: Obrona Helu, literally "the Defense of Hel") was a World War II engagement fought from 1 September to 2 October 1939 on the Hel Peninsula, of the Baltic Sea coast, between invading German forces and defending Polish units during the German invasion of Poland (also known in Polish historiography as the September Campaign). The defense of the Hel Peninsula took place around the Hel Fortified Area, a system of Polish fortifications that had been constructed in the 1930s near the interwar border with the German Third Reich.', 1939, 9, 9, 1939, 10, 2, 'day', '9 September 1939 – 2 October 1939', 53, 'https://en.wikipedia.org/wiki/Battle_of_Hel'),
  ('Q1150620', 'Slovak invasion of Poland', 'The Slovak invasion of Poland occurred during Nazi Germany''s invasion of Poland in September 1939. The recently created Slovak Republic joined the attack, and Field Army Bernolák contributed over 50,000 soldiers in three divisions.', 1939, 9, 16, 1939, 9, 16, 'day', '16 September 1939', 59, 'https://en.wikipedia.org/wiki/Slovak_invasion_of_Poland'),
  ('Q2305266', 'Soviet invasion of Poland', 'The Soviet Union invaded Poland from the east, without a formal declaration of war, on 17 September 1939, 16 days after Nazi Germany invaded Poland from the west. Subsequent military operations lasted for the following 20 days and ended on 6 October 1939 with the two-way division and annexation of the entire territory of the Second Polish Republic by Nazi Germany and the Soviet Union.', 1939, 9, 17, 1939, 10, 6, 'day', '17 September 1939 – 6 October 1939', 76, 'https://en.wikipedia.org/wiki/Soviet_invasion_of_Poland'),
  ('Q2587808', 'The Holocaust in Poland', 'The Holocaust saw the ghettoization, robbery, deportation and mass murder of Jews in occupied Poland by Nazi Germany. Over three million Polish Jews were murdered, primarily at the Chełmno, Belzec, Sobibor, Treblinka and Auschwitz extermination camps, who made up half of the Jewish Holocaust victims.', 1940, NULL, NULL, NULL, NULL, NULL, 'decade', '1940s', 62, 'https://en.wikipedia.org/wiki/The_Holocaust_in_Poland'),
  ('Q60270', 'Battle of the Dukla Pass', 'The Battle of the Dukla Pass, also known as the Dukla, Carpatho–Dukla, Rzeszów–Dukla, or Dukla–Prešov offensive, was the battle for control over the Dukla Pass on the border between Poland and Slovakia on the Eastern Front of World War II between Nazi Germany and the Soviet Union in September–October 1944. It was part of the Soviet east Carpathian strategic offensive that also included the Carpathian–Uzhgorod offensive.', 1944, 9, 8, 1944, 10, 28, 'day', '8 September 1944 – 28 October 1944', 60, 'https://en.wikipedia.org/wiki/Battle_of_the_Dukla_Pass'),
  ('Q159065', 'Vistula–Oder Offensive', 'The Vistula–Oder offensive (Russian: Висло-Одерская операция, romanized: Vislo–Oderskaya operatsiya) was a Red Army operation on the Eastern Front in the European theatre of World War II in January 1945. The army made a major advance into German-held territory, capturing Kraków, Warsaw, and Poznań.', 1945, 1, 12, 1945, 2, 2, 'day', '12 January 1945 – 2 February 1945', 69, 'https://en.wikipedia.org/wiki/Vistula%E2%80%93Oder_offensive'),
  ('Q664581', 'Siege of Breslau', 'The siege of Breslau, also known as the battle of Breslau, was a three-month-long siege of the city of Breslau in Lower Silesia, Germany (now Wrocław, Poland), lasting to the end of World War II in Europe. From 13 February 1945 to 6 May 1945, German troops in Breslau were besieged by the Soviet forces which encircled the city as part of the Lower Silesian Offensive Operation.', 1945, 1, 23, 1945, 5, 6, 'day', '23 January 1945 – 6 May 1945', 55, 'https://en.wikipedia.org/wiki/Siege_of_Breslau'),
  ('Q52967', 'Poznań 1956 protests', 'The first of several massive protests against the communist government of the Polish People''s Republic took place in Poznań from 28 to 30 June 1956. Demonstrations by workers demanding better working conditions began at Poznań''s Cegielski Factories and were met with violent repression.', 1956, 6, NULL, NULL, NULL, NULL, 'month', 'June 1956', 68, 'https://en.wikipedia.org/wiki/1956_Pozna%C5%84_protests'),
  ('Q641309', 'Treaty of Moscow', 'The Treaty of Moscow was signed on 12 August 1970 between the Soviet Union and West Germany. It was signed by Willy Brandt and Walter Scheel for West Germany''s side and by Alexei Kosygin and Andrei Gromyko for the Soviet Union.', 1970, 8, 12, NULL, NULL, NULL, 'day', '12 August 1970', 57, 'https://en.wikipedia.org/wiki/Treaty_of_Moscow_(1970)'),
  ('Q315494', '1997 Central European flood', 'The 1997 Central European flood or the 1997 Oder Flood of the Oder and Morava river basins in July 1997 affected Poland, the Czech Republic and Germany, taking the lives of 114 people and causing material damages estimated at $4.5 billion (3.8 billion euros in the Czech Republic and Poland and 330 million euros in Germany). The flooding began in the Czech Republic, then spread to Poland and Germany.', 1997, 7, 5, 1997, 8, 6, 'day', '5 July 1997 – 6 August 1997', 57, 'https://en.wikipedia.org/wiki/1997_Central_European_flood'),
  ('Q2054084', 'LOT Polish Airlines Flight 16', 'LOT Polish Airlines Flight 16 was a scheduled flight from Newark, United States, to Warsaw, Poland. On 1 November, 2011, the Boeing 767 operating the route made a successful gear-up emergency landing at Warsaw Chopin Airport, after its landing gear failed to extend.', 2011, 11, 1, NULL, NULL, NULL, 'day', '1 November 2011', 57, 'https://en.wikipedia.org/wiki/LOT_Polish_Airlines_Flight_16'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q100791760', 'protests against the tightening of the abortion law in Poland in 2020', 'The 2020–2021 women''s strike protests in Poland, commonly called the Women''s Strike (Polish: Strajk Kobiet), were anti-government demonstrations and protests in Poland that began on 22 October 2020, in reaction to a ruling of the Constitutional Tribunal, mainly consisting of judges who were appointed by the ruling Law and Justice (Polish: Prawo i Sprawiedliwość, PiS) dominated United Right, which tightened the law on abortion in Poland. The ruling made almost all cases of abortion illegal, including those cases in which the foetus had a severe and permanent disability, or an incurable and…', 2020, NULL, NULL, NULL, NULL, NULL, 'year', '2020', 60, 'https://en.wikipedia.org/wiki/2020%E2%80%932021_women''s_strike_protests_in_Poland'),
  ('Q130297776', '2024 Central European floods', 'The 2024 Central European floods were a series of floods caused by a record heavy rainfall generated by Storm Boris, an extremely humid Genoa low. The flooding began in Austria and the Czech Republic, then spread to Poland, Romania and Slovakia, and then onwards to Germany and Hungary.', 2024, 9, NULL, NULL, NULL, NULL, 'month', 'September 2024', 57, 'https://en.wikipedia.org/wiki/2024_Central_European_floods');
